{#- Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/number-field.json
    A narrow number field between a minus and a plus ghost icon button, drawn as one control (4px inside its ring). Static markup: the buttons carry no logic; the page wires them.
    Props (p): value, name, min, label, decrease, increase. -#}
{%- set v_value = (p.value ?? '') -%}
{%- set v_name = (p.name ?? '') -%}
{%- set v_min = (p.min ?? '') -%}
{%- set v_label = (p.label ?? null) -%}
{%- set v_decrease = (p.decrease ?? null) -%}
{%- set v_increase = (p.increase ?? null) -%}
{%- set c_3 -%}
  {%- set c_1 -%}
    {{ include('icons/LucideIcon.html.twig', {'name': 'minus', 'size': 16}, with_context = false) }}
  {%- endset -%}
  {{ include('compose/Button.html.twig', {'variant': 'ghost', 'size': 'sm', 'layout': 'icon', 'type': 'button', 'ariaLabel': og_s(v_decrease), 'children': c_1}, with_context = false) }}
  {{ include('compose/Input.html.twig', {'type': 'number', 'name': og_s(v_name), 'value': og_s(v_value), 'min': og_s(v_min), 'size': 'sm', 'class': 'number-bare w-8 bg-transparent px-0 text-center inset-ring-0', 'attrs': og_attrs(['aria-label', v_label])}, with_context = false) }}
  {%- set c_2 -%}
    {{ include('icons/LucideIcon.html.twig', {'name': 'plus', 'size': 16}, with_context = false) }}
  {%- endset -%}
  {{ include('compose/Button.html.twig', {'variant': 'ghost', 'size': 'sm', 'layout': 'icon', 'type': 'button', 'ariaLabel': og_s(v_increase), 'children': c_2}, with_context = false) }}
{%- endset -%}
{{ include('compose/Box.html.twig', {'class': 'inline-flex h-10 items-center gap-1 rounded bg-background p-1 inset-ring inset-ring-input', 'attrs': og_attrs(['data-slot', 'number-field']), 'children': c_3}, with_context = false) }}
